                    "oneOf": [
                        {
                            "type": "string"
                        },
                        {
                            "type": "object"
                        },
                        {
                            "type": "array"
                        }
                    ]
                }
            },
            "additionalProperties": false,
            "required": [
                "class",
                "id",
                "recipe"
            ]
        },
        "contextualize": {
            "type": "object",
