                    "$ref": "#/definitions/idString"
                },
                "step": {
                    "type": "integer",
                    "minimum": 0
                }
            },
            "additionalProperties": false,
            "required": [
                "system",
                "configure"
            ]
        },
        "deploy": {
            "type": "object",
