                "file_version",
                "file_mtime",
                "file_type",
                "uuid",
                "strings",
                "table_name"
            ],
            "additionalProperties": false
        }
    },
    "oneOf": [
        {
            "$ref": "#/definitions/ecu"
        },
        {
            "$ref": "#/definitions/string_table"
        }
    ]
}

