{
    "$id": "http://pddl-schema.org/ptest.json",
    "type": "object",
    "definitions": {},
    "$schema": "http://json-schema.org/draft-07/schema#",
    "properties": {
        "defaultDomain": {
            "$id": "/properties/defaultDomain",
            "type": "string",
            "title": "The domain file, if common to many of the test cases. The 'domain' property in each individual test case can override this value.",
            "default": "",
            "examples": [
                "domain.pddl"
            ]
        },
        "defaultProblem": {
            "$id": "/properties/defaultProblem",
            "type": "string",
            "title": "The problem file, if common to many of the test cases. The 'problem' property in each individual test case can override this value.",
            "default": "",
            "examples": [
                "problem.pddl"
            ]
        },
        "defaultOptions": {
            "$id": "/properties/defaultOptions",
            "type": "string",
            "title": "The command line options. Set this to empty string to avoid getting asked every time.",
            "default": "",
            "examples": [
                ""
            ]
        },
        "cases": {
            "$id": "/properties/cases",
            "type": "array",
            "items": {
                "$id": "/properties/cases/items",
                "type": "object",
                "properties": {
                    "label": {
                        "$id": "/properties/cases/items/properties/label",
                        "type": "string",
                        "description": "The Label for the test case",
                        "default": "Test XYZ",
                        "examples": [
                            "Test case number 1"
                        ]
                    },
                    "description": {
                        "$id": "/properties/cases/items/properties/description",
                        "type": "string",
                        "description": "The Description for the test case",
                        "default": "Test XYZ...",
                        "examples": [
                            "Given ... when ... then ..."
                        ]
                    },
                    "domain": {
                        "$id": "/properties/cases/items/properties/domain",
                        "type": "string",
                        "description": "The Domain file. Use absolute path, or relative to this ptest manifest file.",
                        "default": "domain.pddl",
                        "examples": [
                            "domain.pddl"
                        ]
                    },
                    "problem": {
                        "$id": "/properties/cases/items/properties/problem",
                        "type": "string",
                        "description": "The Problem file or template.",
                        "default": "problem.pddl",
                        "examples": [
                            "problem.pddl"
                        ]
                    },
                    "options": {
                        "$id": "/properties/cases/items/properties/options",
                        "type": "string",
                        "description": "The command-line options",
                        "default": "",
                        "examples": [
                            "-t 0.001"
                        ]
                    },
                    "preProcess": {
                        "$id": "/properties/cases/items/properties/preProcess",
                        "description": "Pre-processor to execute before launching the planner.",
                        "type": "object",
                        "required": [
                            "kind"
                        ],
                        "properties": {
                            "kind": {
                                "$id": "/properties/cases/items/properties/preProcess/properties/kind",
                                "type": "string",
                                "description": "The kind of pre-processor.",
                                "pattern": "^(nunjucks|jinja2|python|command)$",
                                "default": "nunjucks",
                                "examples": [
                                    "command",
                                    "python",
                                    "nunjucks",
                                    "jinja2"
                                ]
                            },
                            "command": {
                                "$id": "/properties/cases/items/properties/preProcess/properties/command",
                                "type": "string",
                                "description": "The command to execute. Mandatory when 'kind' is set to 'command'.",
                                "default": "",
                                "examples": [
                                    "shell",
                                    "script.bat",
                                    "program.exe"
                                ]
                            },
                            "script": {
                                "$id": "/properties/cases/items/properties/preProcess/properties/script",
                                "type": "string",
                                "description": "The python script to execute. Mandatory when 'kind' is set to 'python'.",
                                "default": "myscript.py",
                                "examples": [
                                    "script.py"
                                ]
                            },
                            "args": {
                                "$id": "/properties/cases/items/properties/preProcess/properties/args",
                                "type": "array",
                                "description": "Command-line arguments",
                                "items": {
                                    "$id": "/properties/cases/items/properties/preProcess/properties/args/items",
                                    "type": "string",
                                    "title": "The command-line argument",
                                    "default": "",
                                    "examples": [
                                        "script.py",
                                        "data.json"
                                    ]
                                }
                            },
                            "data": {
                                "$id": "/properties/cases/items/properties/preProcess/properties/data",
                                "type": "string",
                                "description": "The JSON data file. This property is mandatory if 'kind' is set to 'jinja2' or 'nunjucks'",
                                "default": "case1.json",
                                "examples": [
                                    "data.json"
                                ]
                            }
                        }
                    },
                    "expectedPlans": {
                        "$id": "/properties/cases/items/properties/expectedPlans",
                        "description": "Expected plans - put one or more plan file names here",
                        "type": "array",
                        "items": {
                            "$id": "/properties/cases/items/properties/expectedPlans/items",
                            "type": "string",
                            "title": "Plan file name",
                            "default": ""
                        }
                    }
                }
            }
        }
    }
}

{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "title": "Form meta schema",
    "description": "Schema used for data type validation.",
    "type": "array",
    "minItems": 1,
    "_uniqueItems": true,
    "items": {
        "oneOf": [
            {
                "$ref": "#/types/string"
            },
            {
                "$ref": "#/types/boolean"
            },
            {
                "$ref": "#/types/integer"
            },
            {
                "$ref": "#/types/decimal"
            },
            {
                "$ref": "#/types/date"
            },
            {
                "$ref": "#/types/datetime"
            },
            {
                "$ref": "#/types/secret"
            },
            {
                "$ref": "#/types/file"
            },
            {
                "$ref": "#/types/dir"
            },
            {
                "$ref": "#/types/url"
            },
            {
                "$ref": "#/types/json"
            },
            {
                "$ref": "#/types/list_string"
            },
            {
                "$ref": "#/types/list_integer"
            },
            {
                "$ref": "#/types/list_decimal"
            },
            {
                "$ref": "#/types/list_file"
            },
            {
                "$ref": "#/types/list_dir"
            },
            {
                "$ref": "#/types/list_url"
            }
        ]
    },
    "types": {
        "string": {
            "type": "object",
            "required": [
                "type",
                "value"
            ],
            "additionalProperties": false,
            "properties": {
                "type": {
                    "type": "string",
                    "pattern": "^basic:(string|text):$"
                },
                "value": {
                    "type": "string"
                }
            }
        },
        "boolean": {
            "type": "object",
            "required": [
                "type",
                "value"
            ],
            "additionalProperties": false,
            "properties": {
                "type": {
                    "type": "string",
                    "pattern": "^basic:boolean:$"
                },
                "value": {
                    "type": "boolean"
                }
            }
        },
        "integer": {
            "type": "object",
            "required": [
                "type",
                "value"
            ],
            "additionalProperties": false,
            "properties": {
                "type": {
                    "type": "string",
                    "pattern": "^(basic:integer|data(:[a-z0-9:]+)?):$"
                },
                "value": {
                    "type": "integer"
                }
            }
        },
        "decimal": {
            "type": "object",
            "required": [
                "type",
                "value"
            ],
            "additionalProperties": false,
            "properties": {
                "type": {
                    "type": "string",
                    "pattern": "^basic:decimal:$"
                },
                "value": {
                    "type": "number"
                }
            }
        },
        "date": {
            "type": "object",
            "required": [
                "type",
                "value"
            ],
            "additionalProperties": false,
            "properties": {
                "type": {
                    "type": "string",
                    "pattern": "^basic:date:$"
                },
                "value": {
                    "type": "string",
                    "pattern": "^(19|20)\\d\\d-(0[1-9]|1[012])-(0[1-9]|[12][0-9]|3[01])$"
                }
            }
        },
        "datetime": {
            "type": "object",
            "required": [
                "type",
                "value"
            ],
            "additionalProperties": false,
            "properties": {
                "type": {
                    "type": "string",
                    "pattern": "^basic:datetime:$"
                },
                "value": {
                    "type": "string",
                    "pattern": "^(19|20)\\d\\d-(0[1-9]|1[012])-(0[1-9]|[12][0-9]|3[01]) (?:(?:([01]?\\d|2[0-3]):)?([0-5]?\\d):)?([0-5]?\\d)$"
                }
            }
        },
        "secret": {
            "type": "object",
            "required": [
                "type",
                "value"
            ],
            "additionalProperties": false,
            "properties": {
                "type": {
                    "type": "string",
                    "pattern": "^basic:secret:$"
                },
                "value": {
                    "type": "object",
                    "required": [
                        "handle"
                    ],
                    "additionalProperties": false,
                    "properties": {
                        "handle": {
                            "type": "string",
                            "pattern": "^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$"
                        }
                    }
                }
            }
        },
        "file": {
            "type": "object",
            "required": [
                "type",
                "value"
            ],
            "additionalProperties": false,
            "properties": {
                "type": {
                    "type": "string",
                    "pattern": "^basic:file:(html:)?$"
                },
                "value": {
                    "type": "object",
                    "required": [
                        "file"
                    ],
                    "additionalProperties": false,
                    "properties": {
                        "file": {
                            "type": "string"
                        },
